using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public sealed class QualityEvalTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> GoldenScenarios()
    {
        var json = File.ReadAllText(GoldenPath);
        var scenarios = JsonSerializer.Deserialize<List<GoldenScenario>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var scenario in scenarios)
        {
            yield return new object[] { scenario.Id, scenario.UserMessage, scenario.ExpectedTraits };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenScenarios))]
    public async Task EvaluateScenario(string id, string userMessage, List<string> expectedTraits)
    {
        // Read the custom rubric
        var rubric = await File.ReadAllTextAsync(RubricPath);

        Assert.NotNull(id);
        Assert.NotEmpty(userMessage);
        Assert.NotEmpty(expectedTraits);
        Assert.NotEmpty(rubric);

        // TODO: Wire up the agentic app endpoint and evaluation pipeline.
        // This scaffold validates that golden.json and rubric.md are loadable
        // and scenarios are well-formed. Replace with actual chat completion
        // calls and evaluator scoring once the app endpoint is available.
    }
}

public sealed class GoldenScenario
{
    public string Id { get; set; } = string.Empty;
    public string UserMessage { get; set; } = string.Empty;
    public List<string> ExpectedTraits { get; set; } = new();
}

